/** pcgSql - selectEstiCode - 평가코드 조회 */ SELECT VESTICODE as "vEstiCode" /* 01_평가코드 */ , VESTICODENAME as "vEstiCodeName" /* 02_설명 */ , VESTICODEVIEW as "vEstiCodeView" /* 03_평가코드 View */ , VESTICODEUPDATE as "vEstiCodeUpdate" /* 04_평가코드 갱신 */ FROM TCA4001
VESTICODE LIKE #{vYear} || '%'
ORDER BY VESTICODE DESC

mapper.insert:
/** pcgSql - insertEstiCode - 평가코드 입력 */
INSERT INTO TCA4001 (
     VESTICODE
   , VESTICODENAME
   , VESTICODEVIEW
   , VESTICODEUPDATE
) VALUES
(
     #{vEstiCode}
   , #{vEstiCodeName}
   , #{vEstiCodeView}
   , #{vEstiCodeUpdate}
)

mapper.update:
/** pcgSql - updateEstiCode - 평가코드  수정 */
UPDATE TCA4001

    VESTICODENAME   = #{vEstiCodeName}  , 
    VESTICODEVIEW   = #{vEstiCodeView}  , 
    VESTICODEUPDATE = #{vEstiCodeUpdate}, 


   AND VESTICODE = #{vEstiCode}

mapper.delete:
/** pcgSql - deleteEstiCode - 평가코드 삭제 */
DELETE FROM TCA4001

   AND VESTICODE = #{vEstiCode}

