/** pcgSql - selectProjectCodeList - 과제코드 조회 */ SELECT A.VESTICODE as "vEstiCode" /* 01_평가코드 */ , A.VPROJECTCODE as "vProjectCode" /* 02_과제코드 */ , A.VPROJECTNAME as "vProjectName" /* 03_과제명 */ , A.VDEPTNAME as "vDeptName" /* 04_센터명 */ , A.VGOVNAME as "vGovName" /* 05_부처명 */ , A.VPROJECTDIVISION as "vProjectDivision" /* 06_사업명 */ , A.VTOTSTARTDATE as "vTotStartDate" /* 07_총과제시작일 */ , A.VTOTENDDATE as "vTotEndDate" /* 08_총과제종료일 */ , A.VSTARTDATE as "vStartDate" /* 09_과제시작일 */ , A.VENDDATE as "vEndDate" /* 10_과제종료일 */ , A.VPROJECTPM as "vProjectPm" /* 11_과제 PM */ , B.VNAME as "vProjectPmName" /* _과제 PM 성명 */ , A.VPROJECTEVA as "vProjectEva" /* 12_과제 평가자 */ , C.VNAME as "vProjectEvaName" /* _과제 평가자 성명 */ , A.VPROJECTGOAL as "vProjectGoal" /* 13_과제 목표 */ , A.VPROJECTMILESTONE as "vProjectMilestone" /* 14_평가 기간내 Milestone */ , A.VESTISTEP as "vEstiStep" /* 15_과제 진행단계 */ , A.VDUEDATE1 as "vDueDate1" /* 16_연구원 입력 종료일자 */ , A.VDUEDATE2 as "vDueDate2" /* 17_PM 기여도 평가 종료일자 */ , A.VDUEDATE3 as "vDueDate3" /* 18_연구원 평가확인 종료일자 */ , A.VDUEDATE4 as "vDueDate4" /* 19_센터장 기여도 확인 종료일자 */ , A.VDUEDATE5 as "vDueDate5" /* 20_PM 최종확인 종료일자 */ FROM TCA4003 A, TAA2101 B, TAA2101 C
A.VESTICODE = #{vEstiCode} AND A.VPROJECTPM = B.VEMPLNO(+) AND A.VPROJECTEVA = C.VEMPLNO(+)
AND A.VESTISTEP = #{vEstiStep}
ORDER BY A.VESTICODE, A.VPROJECTCODE

mapper.insert:
/** pcgSql - insertProjectCode - 과제코드 입력 */
INSERT INTO TCA4003 (
     VESTICODE
   , VPROJECTCODE
   , VPROJECTNAME
   , VDEPTNAME
   , VGOVNAME
   , VPROJECTDIVISION
   , VTOTSTARTDATE
   , VTOTENDDATE
   , VSTARTDATE
   , VENDDATE
   , VPROJECTPM
   , VPROJECTEVA
   , VPROJECTGOAL
   , VPROJECTMILESTONE
   , VESTISTEP
   , VDUEDATE1
   , VDUEDATE2
   , VDUEDATE3
   , VDUEDATE4
   , VDUEDATE5
) VALUES
(
     #{vEstiCode}
   , #{vProjectCode}
   , #{vProjectName}
   , #{vDeptName}
   , #{vGovName}
   , #{vProjectDivision}
   , #{vTotStartDate, jdbcType=VARCHAR}
   , #{vTotEndDate, jdbcType=VARCHAR}
   , #{vStartDate, jdbcType=VARCHAR}
   , #{vEndDate, jdbcType=VARCHAR}
   , #{vProjectPm, jdbcType=VARCHAR}
   , #{vProjectEva, jdbcType=VARCHAR}
   , #{vProjectGoal, jdbcType=VARCHAR}
   , #{vProjectMilestone, jdbcType=VARCHAR}
   , #{vEstiStep}
   , #{vDueDate1, jdbcType=VARCHAR}
   , #{vDueDate2, jdbcType=VARCHAR}
   , #{vDueDate3, jdbcType=VARCHAR}
   , #{vDueDate4, jdbcType=VARCHAR}
   , #{vDueDate5, jdbcType=VARCHAR}
)

