/** pcgSql - updateProjectCode - 과제코드 수정 */ UPDATE TCA4003
VPROJECTNAME = #{vProjectName} , VDEPTNAME = #{vDeptName} , VGOVNAME = #{vGovName} , VPROJECTDIVISION = #{vProjectDivision} , VTOTSTARTDATE = #{vTotStartDate} , VTOTENDDATE = #{vTotEndDate} , VSTARTDATE = #{vStartDate} , VENDDATE = #{vEndDate} , VPROJECTPM = #{vProjectPm} , VPROJECTEVA = #{vProjectEva} , VPROJECTGOAL = #{vProjectGoal} , VPROJECTMILESTONE = #{vProjectMilestone}, VESTISTEP = #{vEstiStep} , VDUEDATE1 = #{vDueDate1} , VDUEDATE2 = #{vDueDate2} , VDUEDATE3 = #{vDueDate3} , VDUEDATE4 = #{vDueDate4} , VDUEDATE5 = #{vDueDate5} ,
AND VESTICODE = #{vEstiCode} AND VPROJECTCODE = #{vProjectCode}

