DELETE FROM TCA4003

   AND VESTICODE = #{vEstiCode}

mapper.select:
/** pcgSql - selectProjectCodeExcelList - 과제코드 목록 엑셀 저장 */ SELECT A.VESTICODE as "vEstiCode" /* 01_평가코드 */ , A.VPROJECTCODE as "vProjectCode" /* 02_과제코드 */ , A.VPROJECTNAME as "vProjectName" /* 03_과제명 */ , A.VDEPTNAME as "vDeptName" /* 04_센터명 */ , A.VGOVNAME as "vGovName" /* 05_부처명 */ , A.VPROJECTDIVISION as "vProjectDivision" /* 06_사업명 */ , A.VTOTSTARTDATE as "vTotStartDate" /* 07_총과제시작일 */ , A.VTOTENDDATE as "vTotEndDate" /* 08_총과제종료일 */ , A.VSTARTDATE as "vStartDate" /* 09_과제시작일 */ , A.VENDDATE as "vEndDate" /* 10_과제종료일 */ , A.VPROJECTPM as "vProjectPm" /* 11_과제 PM */ , B.VNAME as "vProjectPmName" /* _과제 PM 성명 */ , A.VPROJECTEVA as "vProjectEva" /* 12_과제 평가자 */ , C.VNAME as "vProjectEvaName" /* _과제 평가자 성명 */ , A.VPROJECTGOAL as "vProjectGoal" /* 13_과제 목표 */ , A.VPROJECTMILESTONE as "vProjectMilestone" /* 14_평가 기간내 Milestone */ , DECODE(A.VESTISTEP, '1', '연구원 입력중/PM 평가중', '2', '연구원 확인중/센터장 확인중', '3', '센터장 반려', '4', 'PM 최종 확인 중', '5', '최종 평가완료', A.VESTISTEP) as "vEstiStep" /* 15_과제 진행단계 */ , A.VDUEDATE1 as "vDueDate1" /* 16_연구원 입력 종료일자 */ , A.VDUEDATE2 as "vDueDate2" /* 17_PM 기여도 평가 종료일자 */ , A.VDUEDATE3 as "vDueDate3" /* 18_연구원 평가확인 종료일자 */ , A.VDUEDATE4 as "vDueDate4" /* 19_센터장 기여도 확인 종료일자 */ , A.VDUEDATE5 as "vDueDate5" /* 20_PM 최종확인 종료일자 */ FROM TCA4003 A, TAA2101 B, TAA2101 C
A.VESTICODE = #{vEstiCode} AND A.VPROJECTPM = B.VEMPLNO(+) AND A.VPROJECTEVA = C.VEMPLNO(+)
AND A.VESTISTEP = #{vEstiStep}
ORDER BY A.VESTICODE, A.VPROJECTCODE

/** pcgSql - selectEmplNoList - 인원마스터 조회 */ SELECT VESTICODE as "vEstiCode" /* 01_평가코드 */ , VEMPLNO as "vEmplNo" /* 02_사번 */ , VNAME as "vName" /* 03_성명 */ , VDEPTNAME as "vDeptName" /* 04_센터명 */ , VTEAMNAME as "vTeamName" /* 05_팀명 */ , VPOSNAME as "vPosName" /* 06_직위명 */ , VPASSWORD as "vPassword" /* 07_암호 */ , VGRADE as "vGrade" /* 08_등급 */ , DECODE(VGRADE, 'A', '관리자' , 'B', 'PM' , 'C', '평가자' , 'E', '피평가자') as "vGradeName" /* 09_등급명 */ , VESTIYN as "vEstiYn" /* 10_평가대상 여부 */ , VRETIREYN as "vRetireYn" /* 11_퇴사여부 */ FROM TCA4002
VESTICODE = #{vEstiCode}
AND VDEPTNAME = #{vDeptName}
AND VGRADE = #{vEstiGrade}
AND VESTIYN = #{vEstiYn}
ORDER BY VGRADE, VDEPTNAME, VNAME

mapper.insert:
/** pcgSql - insertEmplNo - 인원 마스터 입력 */
INSERT INTO TCA4002 (
     VESTICODE
   , VEMPLNO
   , VNAME
   , VDEPTNAME
   , VTEAMNAME
   , VPOSNAME
   , VPASSWORD
   , VGRADE
   , VESTIYN
   , VRETIREYN
) VALUES
(
     #{vEstiCode}
   , #{vEmplNo}
   , #{vName}
   , #{vDeptName, jdbcType=VARCHAR}
   , #{vTeamName, jdbcType=VARCHAR}
   , #{vPosName, jdbcType=VARCHAR}
   , #{vPassword}
   , #{vGrade, jdbcType=VARCHAR}
   , #{vEstiYn}
   , #{vRetireYn}
)

